    // — Señales de CONSULTA —
    const cTiempo   = /(cuanto).{0,15}(demora|tarda|tiempo|dias?|semanas?|plazo)/.test(n) || /(how (long|fast|quick|soon)|demoran?|tardan?|plazo|days? (to|for))/.test(n);
    const cCatalogo = /(que tipos?|what types?|what kind[s]?|what do you (make|offer|sell|have|do)|que (ofrecen|hacen|venden|tienen|manejan|trabajan)|tipos? de|clases? de|opciones?|disponibles?|que (fabrican|producen|construyen))/.test(n);
    const cOper     = /(horario|schedule|hours?|abiertos?|abren|cierran|open|close|located|location|address|direcc|donde estan|donde esta|where are you|work.{0,5}(weekend|saturday|sunday|sabado|domingo|fin de semana)|trabajan.{0,10}(sabado|domingo|fin de semana|weekend)|payment|pago|aceptan|acepta|cobran con|metodo|forma de pag|tarjeta|efectivo|transferencia|deposito|banco|factura|invoice|recibo|estan en|son de|llegan a|near|cerca de)/.test(n);
    const cProceso  = /(como (funciona|trabajan|hacen|es el proceso|se hace)|how (does|do) (it|you|the)|proceso|ispm|nimf|certificad|garantia|warranty|incluye|include|que incluye|included|material|madera|wood|tipo de (madera|material)|que.{0,10}(incluye|viene|trae|contiene))/.test(n);
    const cPueden   = /^(pueden|can you|do you|are you|es posible|hacen|fabrican|manejan|trabajan con|atienden|van a|vienen a|tienen servicio|ofrecen servicio|make|build|deliver|come to|work with|handle)/.test(n);
    const cPrecioG  = /(descuento|discount|precios? (en general|normal|promedio|aprox|standard|habitual)|cuanto salen en promedio|precio base|precio minimo|precio maximo|cuales? son (sus|los) precio|what are (your|the) price|how much (do you|does it) (charge|cost) (in general|usually|typically|on average|generally|normally)|rango de precio|cuanto.{0,10}(salen|valen).{0,10}(mas o menos|aprox|por lo general)|minimo de pedido|minimum order)/.test(n);
    const cInfo     = /(que ofrecen|que hacen|que servicios|what (do|does).{0,10}(offer|make|sell|do)|tell me about|explica|explain|informac|info sobre|more about|servicios que|solo quier.{0,2} saber|just want to know|queria saber)/.test(n);

    // — Señales de COTIZACIÓN —
    const qDirecto   = /(cotiz[a-z]*|presupuest[a-z]*|quot[a-z]*|estimat[a-z]*)/.test(n);
