    const esCotizacion = qDirecto || qNecesidad || qAccion || qPrecEsp || qTengo || qNecEmbal || qMedidas || qSerian || qDame || qEN || qNeedToShip || qPackagingFor || qPrecioProd || qCuantoProd || qISPM;

    if (ambiguo) return 'consulta';
    if (esCotizacion && esConsulta) {
      return (qDirecto || qNecesidad || qPrecEsp || qEN || qDame || qNecEmbal || qNeedToShip || qPackagingFor || qPrecioProd || qCuantoProd || qISPM) ? 'cotizacion' : 'consulta';
