    // Si el mensaje es una presentación de nombre, no clasificar como intento todavía
    const esPresentacionNombre = /^(con\s|soy\s|me\s+llamo\s|mi\s+nombre\s|i'?m\s|my\s+name\s)/i.test(texto);
    if (!esPresentacionNombre) {
      const intento = detectarIntento(texto);
      datosRecolectados.tipo_flujo = (intento === 'cotizacion') ? 'cotizacion' : 'consulta';

      // Si ya menciona el artículo en el mismo mensaje, extraerlo para no preguntar de nuevo
      if (intento === 'cotizacion') {
        const sinPrefijo = texto
          .replace(/^(me gustar[ií]a|quisiera|necesito|quiero|i need|i want|i'?d like|looking for|dame|give me).{0,20}?(cotiz[a-z]*|presupuest[a-z]*|una? cotizaci[oó]n|una? (caja|cajón|cajon|crate|box|embalaje|packaging))?\s+(para\s+|de\s+)?/i, '')
          .replace(/^(para\s+|de\s+|embalar?\s+|empacar?\s+|ship\s+|pack\s+)/i, '')
          .trim();
        if (sinPrefijo.length >= 3 && sinPrefijo.split(/\s+/).length <= 8) {
          datosRecolectados.producto = sinPrefijo;
        }
      }
    }
    // Si es presentación: tipo_flujo queda null → estado se mantiene IDENTIFICAR_NECESIDAD → Parsear da "¡Mucho gusto!"
  }

  // En FLUJO_CONSULTA: detectar si ahora quiere cotizar → cambiar flujo
  if (proximoPasoInicial === 'FLUJO_CONSULTA') {
    const esAfirmacion = /^(s[ií]\b|yes\b|claro\b|dale\b|perfecto\b|adelante\b|por favor\b|ok\b|okay\b|sure\b|please\b|quiero\b|me interesa\b|vamos\b|hagamos\b|genial\b|excelente\b|bueno\b|listo\b|obvio\b|claro que s[ií]|ok perfecto|dale s[ií]|yes please|sure thing|sounds good|de acuerdo|me parece bien|^va$|yes go ahead|claro dale|s[ií] claro|ok s[ií]|si claro|s[ií] me interesa|yes i want|me gustar[ií]a|quisiera|i'?d like|i want|eso me interesa)[.!,\s]*$/i.test(texto.trim().toLowerCase());
    if (esAfirmacion || detectarIntento(texto) === 'cotizacion') {
      datosRecolectados.tipo_flujo = 'cotizacion';
    }
  }

    // PRODUCTO
  if (proximoPasoInicial === 'PEDIR_PRODUCTO' && !isGreeting) {
    datosRecolectados.producto = texto;
  }

  // MEDIDAS
  if (proximoPasoInicial === 'PEDIR_MEDIDAS' && hasDigits) {
    datosRecolectados.medidas = texto.replace(/\$\s*(\d)/g, '$1');
  }

  // TIPO CAJÓN
  if (proximoPasoInicial === 'PEDIR_TIPO_CAJON') {
    const confirma = /^(si\b|sí\b|yes\b|dale|claro|ok\b|bien\b|perfecto|adelante|sure\b|de acuerdo|sounds|me parece|sisi)/i.test(textoLower);
    if (/jaula/i.test(texto))       datosRecolectados.tipo_cajon = 'jaulas';
    else if (/palet|pallet/i.test(texto)) datosRecolectados.tipo_cajon = 'palets_medida';
    else if (/cuna/i.test(texto))   datosRecolectados.tipo_cajon = 'cunas';
    else if (/plataforma/i.test(texto)) datosRecolectados.tipo_cajon = 'plataformas_contenedor';
    else if (/feria/i.test(texto))  datosRecolectados.tipo_cajon = 'embalaje_ferias';
    else if (confirma || /cajon|cajón|cerrado|crate|box/i.test(texto)) datosRecolectados.tipo_cajon = 'cajones_cerrados';
  }

  // PROTECCIÓN
  if (proximoPasoInicial === 'PEDIR_PROTECCION') {
    if (/\b(si\b|sí\b|yes\b|dale|claro|ok\b|quiero|foam|burbuja|esquinera|por favor|please|add|agrega|sisi)\b/i.test(textoLower)) {
      datosRecolectados.proteccion_extra = true;
    } else if (/^(no\b|nope\b|sin |no gracias|no quiero|no thanks|don't|dont|skip|sin protec)/i.test(textoLower)) {
      datosRecolectados.proteccion_extra = false;
    }
  }

  // FECHA
  if (proximoPasoInicial === 'PEDIR_FECHA') {
    const hasFechaRef = hasDigits ||
      /\b(hoy|mañana|manana|tomorrow|today|lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado|domingo|monday|tuesday|wednesday|thursday|friday|saturday|sunday|urgente|asap|as soon as possible|lo antes|inmediato|semana|semanas|mes|meses|month|months|next week|next month|end of|enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre|january|february|march|april|june|july|august|september|october|november|december|primero|próximo|proximo|siguiente|días|dias)\b/i.test(texto);
    if (hasFechaRef) datosRecolectados.fecha = texto;
  }

  // EMAIL (siempre)
  if (!datosRecolectados.correo_contacto && texto.includes('@')) {
    const emailMatch = texto.match(/[\w.+-]+@[\w-]+\.[\w.]+/);
    if (emailMatch) datosRecolectados.correo_contacto = emailMatch[0];
  }
}

// Recalcular tras extracción
proximoPaso = calcProximoPaso(datosRecolectados);
const nombreRecienExtractado = !nombreAntesMensaje && datosRecolectados.nombre_cliente;

// DESPEDIDA
const isCierreSena = /\b(muchas gracias|thank you|thanks a lot|that'?s? all|eso es todo|ya está|nada más|nada mas|hasta luego|bye\b|adiós|adios|hasta pronto|me queda claro|ya tengo lo|con eso basta|no necesito más|ya era todo)\b/i.test(textoLower)
  || /^gracias[.!\s]*$/i.test(textoLower);
if (isCierreSena && (cotizacionEnviada || ['LISTO_PARA_COTIZAR','POST_COTIZACION','FLUJO_CONSULTA'].includes(proximoPaso))) {
  proximoPaso = 'DESPEDIDA';
}

// ── Dimensiones ───────────────────────────────────────────────────────────────
let dimensiones = { largo: null, ancho: null, alto: null };
const medidasStr = datosRecolectados.medidas || '';
if (medidasStr) {
  const dimMatch = medidasStr.match(/(\d+(?:\.\d+)?)\s*[x*×]\s*(\d+(?:\.\d+)?)\s*[x*×]\s*(\d+(?:\.\d+)?)/i);
  if (dimMatch) {
    dimensiones = { largo: parseFloat(dimMatch[1]), ancho: parseFloat(dimMatch[2]), alto: parseFloat(dimMatch[3]) };
  } else {
    const nums = medidasStr.match(/\d+(?:\.\d+)?/g);
    if (nums && nums.length >= 3) dimensiones = { largo: parseFloat(nums[0]), ancho: parseFloat(nums[1]), alto: parseFloat(nums[2]) };
  }
}

const tipoCajaApiMap = { cajones_cerrados:'cajones_cerrados', jaulas:'jaulas', palets_medida:'palets_medida', cunas:'cunas', plataformas_contenedor:'plataformas_contenedor', embalaje_ferias:'embalaje_ferias', mayor:'mayor' };
const tipoCajaApi = tipoCajaApiMap[datosRecolectados.tipo_cajon] || null;
const todosRecolectados = proximoPaso === 'LISTO_PARA_COTIZAR';

// ── Prompt para la IA ─────────────────────────────────────────────────────────
const nombre = (datosRecolectados.nombre_cliente || '').replace(/[`$\\]/g, '');
const producto = datosRecolectados.producto || '';
const medidas  = datosRecolectados.medidas || '';

// ── Detección de pregunta intercalada en medio de cotización ─────────────────
// Cuando el cliente hace una consulta durante la recolección de datos, la IA
// responde la pregunta y recuerda amablemente el dato pendiente.
const estadosRecoleccion = ['PEDIR_MEDIDAS', 'PEDIR_TIPO_CAJON', 'PEDIR_PROTECCION', 'PEDIR_FECHA'];
const esPreguntaIntercalada = estadosRecoleccion.includes(proximoPasoInicial)
  && (/[?¿]/.test(texto) || detectarIntento(texto) === 'consulta')
  && !( // Excepto si el mensaje también provee el dato esperado
    (proximoPasoInicial === 'PEDIR_MEDIDAS' && hasDigits) ||
    (proximoPasoInicial === 'PEDIR_TIPO_CAJON' && datosRecolectados.tipo_cajon) ||
    (proximoPasoInicial === 'PEDIR_PROTECCION' && datosRecolectados.proteccion_extra !== null && datosRecolectados.proteccion_extra !== undefined) ||
    (proximoPasoInicial === 'PEDIR_FECHA' && datosRecolectados.fecha)
  );

let tareaIA;

if (esPreguntaIntercalada) {
  const datoPendiente = {
    PEDIR_MEDIDAS: 'las medidas del artículo (Largo × Ancho × Alto)',
    PEDIR_TIPO_CAJON: 'el tipo de embalaje preferido (cajón cerrado, jaula, paleta, etc.)',
    PEDIR_PROTECCION: 'si necesita protección interior adicional',
    PEDIR_FECHA: 'la fecha en que necesita el embalaje',
  }[proximoPasoInicial] || 'el dato pendiente';
  const catalogoCtx = catalogoFinal ? `\n\nCatálogo CE: ${catalogoFinal}` : '';
  tareaIA = `El cliente pregunta: "${texto}" mientras cotizamos embalaje para "${producto}". Responde brevemente. Luego en UNA oración recuérdale que aún necesitas ${datoPendiente}.${catalogoCtx}`;

} else if (proximoPaso === 'PRIMER_CONTACTO') {
  tareaIA = `PRIMER CONTACTO. Escribe EXACTAMENTE (sin comillas, sin cambiar nada):\n${saludo}, soy Alex, el asistente de Crating Express. ¿Con quién tengo el gusto?`;

} else if (proximoPaso === 'PEDIR_NOMBRE') {
  tareaIA = `El cliente no ha dicho su nombre. Pregúntale amigablemente: "¿Con quién tengo el gusto?"`;

} else if (proximoPaso === 'IDENTIFICAR_NECESIDAD') {
  tareaIA = nombreRecienExtractado
    ? `El cliente acaba de dar su nombre: "${nombre}". Salúdalo: "¡Mucho gusto, ${nombre}!" y pregunta en qué puedes ayudarle hoy.`
    : `Saluda a ${nombre} por su nombre y pregunta en qué puedes ayudarle hoy.`;

} else if (proximoPaso === 'FLUJO_CONSULTA') {
  const catalogoCtx = catalogoFinal ? `\n\nCatálogo CE: ${catalogoFinal}` : '';
  tareaIA = `El cliente tiene una consulta: "${texto}". Respóndela brevemente con lo que sabes de Crating Express (embalajes madera a medida, ISPM-15, servicio en Miami, cajones cerrados, jaulas, paletas, cunas, plataformas para contenedor, embalaje para ferias).${catalogoCtx}\nSi la respuesta puede derivar en una cotización, al final ofrécela naturalmente con una frase como "¿Te gustaría una cotización para algo específico?"`;

} else if (proximoPaso === 'PEDIR_PRODUCTO') {
  tareaIA = `El cliente quiere cotizar. Pregunta qué artículo específico necesita embalar.`;

} else if (proximoPaso === 'PEDIR_MEDIDAS') {
  tareaIA = `Artículo: "${producto}". Pide las medidas en pulgadas (Largo × Ancho × Alto) y el peso aproximado en libras.`;

} else if (proximoPaso === 'PEDIR_TIPO_CAJON') {
  tareaIA = `Artículo: "${producto}", medidas: ${medidas}. Recomienda cajón cerrado para máxima protección con ISPM-15 y pregunta si está bien. Una sola oración.`;

} else if (proximoPaso === 'PEDIR_PROTECCION') {
  tareaIA = `Tipo de cajón confirmado. Pregunta si desea protección interior (foam, burbuja o esquineras) con costo adicional. Solo esa pregunta.`;

} else if (proximoPaso === 'PEDIR_FECHA') {
  tareaIA = `Ya tienes producto, medidas, cajón y protección. Pregunta SOLO: ¿para cuándo necesita el embalaje?`;

} else if (proximoPaso === 'LISTO_PARA_COTIZAR') {
  tareaIA = `Todos los datos listos. Mensaje breve: vas a calcular el estimado para "${producto}". NO menciones precios.`;

} else if (proximoPaso === 'POST_COTIZACION') {
  tareaIA = datosRecolectados.correo_contacto
    ? `Ya tienes el correo "${datosRecolectados.correo_contacto}". Confirma que un especialista se pondrá en contacto y despídete.`
    : `Cotización enviada. Pregunta el correo para que un especialista de Crating Express pueda contactarle.`;

} else if (proximoPaso === 'DESPEDIDA') {
  tareaIA = `El cliente termina la conversación. Despídete cordialmente y agradece su contacto.`;

} else {
  tareaIA = `Responde al mensaje del cliente de forma natural.`;
}

const sistemaIA = `Eres Alex, asistente de Crating Express en Miami. Embalajes de madera a medida, ISPM-15 incluido. Responde en el idioma del cliente (español o inglés). Profesional, amigable, muy conciso — máximo 2 oraciones. Ejecuta ÚNICAMENTE la tarea indicada. NUNCA menciones precios (el sistema los calcula). NUNCA hagas preguntas extra.`;
const usuarioIA = `${tareaIA}\n\nMensaje del cliente: "${texto}"`;

return [{ json: {
  telefono: msgData.telefono,
  texto, nombreContacto: msgData.nombreContacto || '',
  emailVendedor, followup24, followup72,
  leadId, estado, historial,
  datosRecolectados, cotizacionEnviada, esNuevo,
  saludoHora, catalogoProductos,
  proximoPaso, dimensiones, tipoCajaApi, todosRecolectados,
  nombreRecienExtraido, nombreAntesMensaje,
  sistemaIA, usuarioIA
} }];

