const msgs = {
  PRIMER_CONTACTO:     `${s}, soy Alex, el asistente de Crating Express. ¿Con quién tengo el gusto?`,
  PEDIR_NOMBRE:        '¿Con quién tengo el gusto?',
  IDENTIFICAR_NECESIDAD: n ? `¡Mucho gusto, ${n}! ¿En qué puedo ayudarte hoy?` : '¿En qué puedo ayudarte hoy?',
  FLUJO_CONSULTA:      'Con gusto te ayudo. ¿Tienes alguna pregunta específica sobre nuestros servicios de embalaje?',
  PEDIR_PRODUCTO:      '¿Qué artículo necesitas embalar?',
  PEDIR_MEDIDAS:       '¿Cuáles son las medidas en pulgadas? (Largo × Ancho × Alto) y el peso en libras.',
  PEDIR_TIPO_CAJON:    `Para ${d.producto||'el artículo'}, recomiendo cajón cerrado para máxima protección. ¿Te parece bien?`,
  PEDIR_PROTECCION:    '¿Deseas protección interior (foam, burbuja o esquineras)? Tiene costo adicional.',
  PEDIR_FECHA:         '¿Para cuándo necesitas el embalaje listo?',
  LISTO_PARA_COTIZAR:  `Perfecto, calculando tu estimado para ${d.producto||'el artículo'}...`,
  POST_COTIZACION:     d.correo_contacto ? '¡Perfecto! Un especialista te contactará pronto.' : '¿Me das tu correo para que el especialista pueda contactarte?',
  DESPEDIDA:           '¡Muchas gracias por contactarnos! Estamos disponibles cuando nos necesites. ¡Que tengas excelente día! 🙌',
};

return [{ json: { _contingencia: true, mensaje: msgs[paso] || '¿En qué más puedo ayudarte?' } }];

