const raw = $input.item.json;
const ctx = $('🔧 Preparar Contexto IA').item.json;

// Get message from AI (plain text) or Contingencia (direct object)
let mensaje;
if (raw._contingencia) {
  mensaje = raw.mensaje || '¿En qué más puedo ayudarte?';
} else {
  mensaje = (raw.choices?.[0]?.message?.content || raw.mensaje || '').trim();
  if (!mensaje) mensaje = '¿En qué más puedo ayudarte?';
}

// TODOS los estados de recolección son deterministas — la IA no puede desviarse
const saludo = ctx.saludoHora.charAt(0).toUpperCase() + ctx.saludoHora.slice(1);
const n = ctx.datosRecolectados?.nombre_cliente || '';
const mensajesDeterministas = {
  PRIMER_CONTACTO:       `${saludo}, soy Alex, el asistente de Crating Express. ¿Con quién tengo el gusto?`,
  PEDIR_NOMBRE:          '¿Con quién tengo el gusto?',
  IDENTIFICAR_NECESIDAD: n ? `¡Mucho gusto, ${n}! ¿En qué puedo ayudarte hoy?` : '¿En qué puedo ayudarte hoy?',
  PEDIR_PRODUCTO:        '¿Qué artículo necesitas embalar?',
  PEDIR_MEDIDAS:         '¿Cuáles son las medidas del artículo? (largo × ancho × alto, en pulgadas o centímetros)',
  PEDIR_TIPO_CAJON:      '¿Qué tipo de embalaje prefieres? Cajón cerrado (máxima protección), jaula (más liviana) o paleta/plataforma.',
  PEDIR_PROTECCION:      '¿Necesitas protección interior adicional como foam, burbuja o esquineras? Ten en cuenta que tiene costo adicional.',
  PEDIR_FECHA:           '¿Para cuándo necesitas el embalaje?',
  DESPEDIDA:             '¡Muchas gracias por contactarnos! Estamos disponibles cuando nos necesites. ¡Que tengas excelente día! 🙌',
};

if (mensajesDeterministas[ctx.proximoPaso]) {
  mensaje = mensajesDeterministas[ctx.proximoPaso];
}

// NOMBRE RECIÉN EXTRAÍDO: siempre "¡Mucho gusto!" sin importar estado ni tipo_flujo
if (ctx.nombreRecienExtraido && ctx.datosRecolectados?.nombre_cliente) {
  mensaje = `¡Mucho gusto, ${ctx.datosRecolectados.nombre_cliente}! ¿En qué puedo ayudarte hoy?`;
}

// FLUJO_CONSULTA: IA responde libre — override en saludo puro o presentación de nombre
if (ctx.proximoPaso === 'FLUJO_CONSULTA') {
  const msgLow = (ctx.texto || '').toLowerCase().trim();
  const esSoloSaludo = /^(hola|hi|hey|buenas|buenos|good\s*(morning|afternoon|evening)|hello|holas?)[.!\s]*$/.test(msgLow);
  const esPresentacion = /^(con\s|soy\s|me\s+llamo\s|mi\s+nombre\s|i'?m\s|my\s+name\s)/i.test(ctx.texto || '');
  if (esSoloSaludo || esPresentacion) {
    mensaje = n ? `¿En qué puedo ayudarte hoy, ${n}?` : '¿En qué puedo ayudarte hoy?';
  }
}

// State entirely from code
const datosRecolectados = ctx.datosRecolectados;
const proximoPaso = ctx.proximoPaso;
const todosRecolectados = ctx.todosRecolectados;
const dimensiones = ctx.dimensiones;
const tipoCajaApi = ctx.tipoCajaApi;

// Clasificacion
let clasificacion = null;
if (datosRecolectados.correo_contacto && (proximoPaso === 'POST_COTIZACION' || ctx.cotizacionEnviada)) {
  clasificacion = 'Caliente';
}

// Estado Airtable
let nuevoEstado = ctx.estado;
if (clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (todosRecolectados && !ctx.cotizacionEnviada) nuevoEstado = 'Calificado';
else if (!ctx.leadId || nuevoEstado === 'Nuevo') nuevoEstado = 'En calificación';

const ts = new Date().toISOString();
// Truncar respuesta a límite WhatsApp (4096 chars) con margen de seguridad
if (mensaje.length > 3800) {
  mensaje = mensaje.slice(0, 3750) + '…';
}

const nuevoHistorial = (ctx.historial ? ctx.historial + '\n' : '') +
  `[${ts}] Cliente: ${ctx.texto}\n[${ts}] Bot: ${mensaje}`;

return [{ json: {
  ...ctx,
  mensaje,
  mensajeRespuesta: mensaje,
  datosRecolectados,
  todos_recolectados: todosRecolectados,
  todosRecolectados,
  dimensiones,
  tipo_caja_api: tipoCajaApi,
  cotizador_enviado: false,
  cotizadorEnviado: false,
  clasificacion,
  resumenLead: todosRecolectados ? `${datosRecolectados.producto || ''} — ${datosRecolectados.medidas || ''}` : '',
  nuevoEstado,
  nuevoHistorial
} }];

